/**
 * Generates a TypeScript file that maps route names to their URL patterns.
 * The generated file exports a `HandlerFor` type that provides type-safe
 * handlers without circular references through RegisteredRoutes.
 */
export function generateRouteTypesSource(
  routeManifest: Record<string, string>
): string {
  const entries = Object.entries(routeManifest).sort(([a], [b]) =>
    a.localeCompare(b)
  );

  const interfaceBody = entries
    .map(([name, pattern]) => `  "${name}": "${pattern}";`)
    .join("\n");

  return `// Auto-generated by @rangojs/router - do not edit
import type { Handler, DefaultEnv } from "@rangojs/router";

// Route name -> pattern mapping (generated from route definitions)
interface GeneratedRouteMap {
${interfaceBody}
}

// Type-safe handler for a named route
export type HandlerFor<
  TRouteName extends keyof GeneratedRouteMap,
  TEnv = DefaultEnv,
> = Handler<GeneratedRouteMap[TRouteName], TEnv>;
`;
}
